import torch
import torch.nn as nn

class ModelNew(nn.Module):
    def __init__(self, dim: int):
        super().__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Custom CUDA operator for argmax over specified dimension
        # Using inlined CUDA kernel for efficiency
        return torch.argmax(x, dim=self.dim)

# Define the custom CUDA kernel for element-wise argmax operation
elementwise_argmax_kernel = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void elementwise_argmax_kernel(const float* x, int dim, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        // Compute argmax along the specified dimension
        int max_idx = 0;
        for (int i = 1; i < dim; ++i) {
            if (x[idx + i, ...] > x[max_idx, ...]) {
                max_idx = i;
            }
        }
        out[idx] = x[max_idx, ...];
    }
}

torch::Tensor elementwise_argmax_cuda(torch::Tensor x) {
    auto size = x.numel();
    auto out = torch.zeros_like(x);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    elementwise_argmax_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), dim, out.data_ptr<float>(), size);

    return out;
}
"""

